// "What If You Had Luffy's Powers in Real Life?" — pilot. 3D environments; every character and prop is original 2D art.
// New series look: fixed HUD (title, DAY N · time, power-status chip), game-interface labels, one-line captions with a
// yellow key word, a white "punch" flash on power cuts, and dark "dossier" infographic cards.
import { f, esc, put, top, bubble, shade, walk, sh, mv, proj, P2, CAST, ease, clamp, registerShot,
  P_STAND, P_FLOAT, P_POINT, P_HIPS, P_PRESENT, P_THINK, P_SHRUG, P_TIRED, P_PHONE, P_RUN } from '../lib/storykit.js';
import { person } from '../lib/char2d.js';
import { hud, label, caption, punch, speedLines, COL, MONO } from '../lib/hud.js';
import * as L from '../lib/luffy.js';

const HERO = 'heroHoodie';
const ST = { none: { text: 'POWER · ???', on: false }, rubber: { text: 'RUBBER · ON', on: true, color: COL.red }, off: { text: 'RUBBER · IDLE', on: false } };
// wrap a shot's ui with the HUD + caption; day/time/status per shot
const chrome = (U, t, info, d) => { hud(U, d); caption(U, info, t); };

// ---------------------------------------------------------------- dossier cards (infographic style for this series)
function dossier(U, id, tt) {
  let g = `<rect width="1920" height="1080" fill="#0c1226"/>`;
  for (let x = 0; x <= 1920; x += 80) g += `<line x1="${x}" y1="0" x2="${x}" y2="1080" stroke="#16204a" stroke-width="2"/>`;
  for (let y = 0; y <= 1080; y += 80) g += `<line x1="0" y1="${y}" x2="1920" y2="${y}" stroke="#16204a" stroke-width="2"/>`;
  for (const [x, y, sx, sy] of [[90, 150, 1, 1], [1830, 150, -1, 1], [90, 990, 1, -1], [1830, 990, -1, -1]]) g += `<path d="M ${x} ${y + sy * 60} L ${x} ${y} L ${x + sx * 60} ${y}" fill="none" stroke="${COL.yellow}" stroke-width="5"/>`;
  g += `<circle cx="${f(960 + Math.sin(tt * 0.4) * 600)}" cy="${f(540 + Math.cos(tt * 0.3) * 300)}" r="420" fill="#1c2a6a" opacity="0.25"/>`;
  U.svg('bg', g, { z: 1 });
}
const TXT = (px, col = '#fff') => `font:900 ${px}px Inter;letter-spacing:-.01em;line-height:1.04;color:${col}`;
let hide = false;
function dcard(id, o) {
  registerShot(id, { bg: '#0c1226', theme: 'dark',
    ui(U, t, info) { const tt = info.start + t; dossier(U, id, tt); hide = false; if (o.draw) o.draw(U, t, info, tt);
      const a = clamp((t - (o.at ? info.w(o.at, 0.15) : 0.1)) / 0.2);
      if (hide) U.html('dc', '', {}); else if (o.text || o.kicker || o.value) U.html('dc', `<div style="width:${o.width || 1500}px;opacity:${f(a)};transform:translateY(${f((1 - a) * 20)}px)">${o.kicker ? `<div style="font:800 30px ${MONO};letter-spacing:.18em;color:${COL.yellow};margin-bottom:14px">${esc(o.kicker)}</div>` : ''}${o.value ? `<div style="${TXT(150)}">${esc(o.value)}</div>` : ''}${o.text ? `<div style="${TXT(o.fs || 84)}">${esc(o.text)}</div>` : ''}${o.sub ? `<div style="font:600 34px Inter;color:#b9c4e8;margin-top:12px">${esc(o.sub)}</div>` : ''}</div>`, { left: (o.left ?? 160) + 'px', top: (o.top ?? 220) + 'px' });
      chrome(U, t, info, o.hud || {}); } });
}

// ---------------------------------------------------------------- the subway (cold open)
const SUB = { base: 'studio', fog: { color: '#cfd2d6', density: 0.01 } };
const H0 = { day: 1, time: '7:58 AM', status: ST.none };
const crowdAt = (U, st, tt, o = {}) => { const tops = ['#5a6e8a', '#7a5ea8', '#4f8a5b', '#c86a8a', '#e0b44a', '#3a3d42', '#8a5a3a']; for (let i = 0; i < (o.n || 9); i++) { const x = -3 + i * 1.3 + Math.sin(i * 2.1) * 0.4, z = -0.8 + (i % 3) * 0.7; put(U, st, 'p' + i, [x, 0, z], 1.62 + (i % 3) * 0.08, i % 4 === 3 ? walk(tt + i, 4) : { ...P_PHONE, head: 18 }, { top: tops[i % tops.length], bottom: i % 2 ? '#2a2d3a' : '#3a3f4a', sleeves: i % 2 ? 'long' : 'short', shoes: '#22242a', hair: i % 3 === 0 ? 'ponytail' : undefined }, { face: 'neutral', flip: i % 2 === 0, look: 0.6 }, { extra: (c) => `<rect x="${f(c.head[0] + (i % 2 ? -1 : 1) * c.R * 0.5 - c.R * 0.3)}" y="${f(c.head[1] + c.R * 1.2)}" width="${f(c.R * 0.6)}" height="${f(c.R * 0.9)}" rx="4" fill="#9fd0ff"/>` }); } };
const SW = { pos: [-1.0, 2.0, 8.5], look: [-2.0, 1.4, 2.4], fov: 52 };
const heroStairs = (U, st, pose, face, at = [-6.3, 0.3, 3.1]) => put(U, st, 'hero', at, 1.6, pose, HERO, { face, rim: '#fff2d6', look: 0.5 });
sh('s001', 'subway', SUB, { cam: [{ pos: [-2, 2.6, 10], look: [-8, 2.0, 3], fov: 46 }, { pos: [-2.5, 2.5, 9], look: [-8, 1.8, 3], fov: 46 }],
  ui(U, t, info, S, st, tt) { crowdAt(U, st, tt, { n: 5 }); const k = clamp(t / 2.6); heroStairs(U, st, walk(tt, 5), 'neutral', [-9 + k * 2.6, 1.8 - k * 1.5, 3.1]); chrome(U, t, info, H0); } });
sh('s002', 'subway', SUB, { cam: [{ pos: [-2.6, 1.6, 7], look: [-6.4, 1.2, 3], fov: 42 }], shake: 0.012,
  ui(U, t, info, S, st, tt) { const k = ease.in(clamp(t / 2.2)); heroStairs(U, st, { ...P_STAND, lean: -18 - k * 40, aL: [140, 150], aR: [120, 160], lL: [30, 30], head: -20 }, 'open', [-6.3 + k * 0.6, 0.3, 3.1]); crowdAt(U, st, tt, { n: 6 }); chrome(U, t, info, H0); } });
// the stretching arm: from the hero's shoulder to a world point, growing over k
const armTo = (U, st, c, P, k, o = {}) => { if (!c) return; const S = L.shoulder(c, 1), q = proj(st, P); if (!q.ok) return; const H = [S[0] + (q.x - S[0]) * k, S[1] + (q.y - S[1]) * k]; U.svg('arm', L.stretchArm(S, H, c.R * 0.45, c.R * 2.4, { sleeve: CAST.heroHoodie.top, lines: k > 0.3 && k < 1 }), { z: 30 }); return H; };
sh('s003', 'subway', SUB, { cam: [SW], ui(U, t, info, S, st, tt) { punch(U, t); const c = heroStairs(U, st, { ...P_STAND, lean: -50, aL: [140, 150], aR: [8, 0], head: -20 }, 'open', [-5.8, 0.3, 3.1]); const H = armTo(U, st, c, [2, 1.0, 2.2], ease.out(clamp(t / 1.6)) * 0.55); if (c) speedLines(U, c.head[0], c.head[1], tt, { op: 0.35, z: 25 }); crowdAt(U, st, tt); chrome(U, t, info, { ...H0, status: ST.rubber }); } });
sh('s004', 'subway', SUB, { cam: [SW, mv(SW, [0.5, 0, -1])], ui(U, t, info, S, st, tt) { const c = heroStairs(U, st, { ...P_STAND, lean: -50, aL: [140, 150], aR: [8, 0], head: -20 }, 'open', [-5.8, 0.3, 3.1]); armTo(U, st, c, [2, 1.0, 2.2], 0.55 + 0.45 * ease.out(clamp(t / 1.2))); crowdAt(U, st, tt); label(U, 'l1', 'STRETCH · 4 M', 0.9, t, 1240, 260); label(U, 'l2', 'ARM THICKNESS · ↓', 1.5, t, 1240, 350, { color: COL.red }); chrome(U, t, info, { ...H0, status: ST.rubber }); } });
sh('s005', 'subway', SUB, { cam: [SW], ui(U, t, info, S, st, tt) { const pull = ease.inOut(clamp((t - 1.4) / 1.6)); const at = [-5.8 + pull * 6.6, 0.3 - pull * 0.3, 3.1 - pull * 0.8]; const c = heroStairs(U, st, pull < 1 ? { ...P_FLOAT, lean: 30 } : P_STAND, pull < 1 ? 'open' : 'neutral', at); const q = proj(st, [2, 1.0, 2.2]); if (c && q.ok && pull < 1) { const S = L.shoulder(c, 1); U.svg('arm', L.stretchArm(S, [q.x, q.y], c.R * 0.45, c.R * 2.4, { sleeve: CAST.heroHoodie.top }) + `<circle cx="${f(q.x)}" cy="${f(q.y)}" r="${f(c.R * 0.5)}" fill="none" stroke="#0b0b10" stroke-width="${f(c.R * 0.25)}"/>`, { z: 30 }); } else U.svg('arm', '', {}); crowdAt(U, st, tt); label(U, 'l1', 'BUNGEE MODE', 0.6, t, 1240, 260); chrome(U, t, info, { ...H0, status: ST.rubber }); } });
sh('s006', 'subway', SUB, { cam: [{ pos: [0, 1.6, 6.5], look: [0, 1.5, 0], fov: 48 }], ui(U, t, info, S, st, tt) { crowdAt(U, st, tt); label(U, 'l1', 'WITNESSES · 0', 0.3, t, 1300, 260); chrome(U, t, info, { ...H0, status: ST.off }); } });
sh('s007', 'subway', SUB, { cam: [{ pos: [0.6, 1.55, 4.6], look: [0.4, 1.45, 1.6], fov: 40 }], ui(U, t, info, S, st, tt) { crowdAt(U, st, tt, { n: 6 }); const lh = info.w('You look at your hand', 2.4); put(U, st, 'hero', [0.8, 0, 1.8], 1.6, t > lh ? { ...P_STAND, aR: [60, 150], head: 20 } : P_STAND, HERO, { face: 'neutral', flip: true, look: -0.3, rim: '#fff2d6' }); label(U, 'l1', 'EYES ON PHONES · 100%', 0.3, t, 1180, 260); chrome(U, t, info, { ...H0, status: ST.off }); } });
// close-up of the hand: drawn
const handCU = (U, t, tt, o = {}) => { let g = `<rect width="1920" height="1080" fill="#d9dcd8"/><rect width="1920" height="1080" fill="url(#tl)" opacity="0.4"/><defs><pattern id="tl" width="80" height="40" patternUnits="userSpaceOnUse"><rect width="80" height="40" fill="none" stroke="#c4c8c4" stroke-width="2"/></pattern></defs>`;
  const wob = o.wobble ? Math.sin(tt * 30) * 6 * o.wobble : 0; g += `<g transform="translate(${f(960 + wob)} 640)"><rect x="-140" y="80" width="280" height="480" rx="80" fill="${CAST.heroHoodie.top}" stroke="#1b1410" stroke-width="6"/><circle cx="0" cy="0" r="150" fill="#0b0b10"/>${[-110, -55, 0, 55].map((x, i) => `<rect x="${x - 22}" y="-${250 + (i % 2) * 20}" width="44" height="${180 + (i % 2) * 20}" rx="22" fill="#0b0b10"/>`).join('')}<rect x="110" y="-120" width="44" height="150" rx="22" fill="#0b0b10" transform="rotate(30 130 -40)"/></g>`;
  U.svg('hand', g, { z: 2 }); };
registerShot('s008', { bg: '#d9dcd8', theme: 'light', ui(U, t, info) { handCU(U, t, info.start + t); label(U, 'l1', 'HAND · NORMAL ?', 0.3, t, 1240, 280); chrome(U, t, info, { ...H0, status: ST.off }); } });
registerShot('s009', { bg: '#0b0b10', theme: 'dark', ui(U, t, info) { const tt = info.start + t; const beats = ['Boom', 'Boom.', 'Boom. Boom'].map((p, i) => info.w(p, 1.2 + i * 1.0)); U.svg('dk', `<rect width="1920" height="1080" fill="#0b0b10"/>` + L.drum(960, 560, tt, 70, 120, COL.red) + `<path d="M 960 640 C 860 560 820 470 900 440 C 940 425 960 460 960 480 C 960 460 980 425 1020 440 C 1100 470 1060 560 960 640 Z" fill="${COL.red}" transform="translate(960 540) scale(${f(1.6 + 0.15 * Math.max(0, Math.sin(tt * 7.3)))}) translate(-960 -540)"/>`, { z: 2 });
  let words = ''; beats.forEach((b, i) => { if (t > b) words += `<div style="${TXT(110, i === 2 ? COL.yellow : '#fff')};position:absolute;left:${300 + i * 520}px;top:${200 + (i % 2) * 520}px;transform:rotate(${i % 2 ? 6 : -6}deg)">BOOM</div>`; }); U.html('bm', `<div style="position:relative;width:1920px;height:1080px">${words}</div>`, { left: '0px', top: '0px' }); chrome(U, t, info, { ...H0, status: ST.off }); } });

// ---------------------------------------------------------------- the premise (dossier cards)
const H1 = { day: 1, time: '7:59 AM', status: ST.rubber };
const silhouette = (x, y, h, o = {}) => person(x, y, h, o.pose || P_STAND, { ...CAST.heroHoodie, face: o.face || 'neutral', rim: '#ffd23f' }).svg;
dcard('s010', { kicker: 'OVERNIGHT, YOU GOT', text: "the powers of Monkey D. Luffy", fs: 96, sub: 'from One Piece', hud: H1, draw: (U, t, info, tt) => U.svg('sil', silhouette(1560, 1000, 560, { pose: P_HIPS, face: 'smile' }) + L.drum(1560, 520, tt, 70, 70, '#ffd23f'), { z: 3 }) });
const xmark = (x, y, ok) => ok ? `<path d="M ${x - 40} ${y} l 28 30 l 56 -64" fill="none" stroke="#4fd06a" stroke-width="14" stroke-linecap="round"/>` : `<path d="M ${x - 36} ${y - 36} l 72 72 M ${x + 36} ${y - 36} l -72 72" stroke="${COL.red}" stroke-width="14" stroke-linecap="round"/>`;
dcard('s011', { hud: H1, draw: (U, t, info) => { const rows = [['STRAW HAT', 'Not his straw hat', false], ['CREW', 'Not his crew', false], ['BODY', 'Just his body', true]]; let g = ''; rows.forEach(([lab, ph, ok], i) => { const a = info.w(ph, 0.3 + i * 1.2); if (t < a) return; const y = 330 + i * 190; g += `<rect x="460" y="${y - 70}" width="1000" height="140" rx="18" fill="#141c3a" stroke="${ok ? '#4fd06a' : '#2a3460'}" stroke-width="4"/><text x="520" y="${y + 22}" font-family="IBM Plex Mono" font-weight="800" font-size="56" fill="#fff">${lab}</text>` + xmark(1360, y, ok); }); U.svg('rows', g, { z: 3 }); } });
const gearSlots = (U, t, info, tt, lit) => { let g = ''; const names = ['GEAR 2', 'GEAR 3', 'GEAR 4', 'GEAR 5']; names.forEach((n, i) => { const x = 260 + i * 370, on = i < 3 ? t > info.w('Four gears', 2.0) : lit; const five = i === 3; g += `<rect x="${x}" y="560" width="320" height="220" rx="22" fill="${five && on ? '#f4f1ff' : '#141c3a'}" stroke="${on ? (five ? '#ffffff' : COL.red) : '#2a3460'}" stroke-width="6"/><text x="${x + 160}" y="690" text-anchor="middle" font-family="IBM Plex Mono" font-weight="800" font-size="50" fill="${five && on ? '#0c1226' : '#fff'}">${n}</text>` + (five && on ? `<circle cx="${x + 160}" cy="670" r="${f(160 + 20 * Math.sin(tt * 6))}" fill="#ffffff" opacity="0.12"/>` : '') + (five && !on ? `<text x="${x + 160}" y="750" text-anchor="middle" font-family="IBM Plex Mono" font-size="28" fill="#5a6490">LOCKED</text>` : ''); }); U.svg('gears', g, { z: 3 }); };
dcard('s012', { kicker: 'BODY', text: 'Rubber.', fs: 130, top: 180, hud: H1, draw: (U, t, info, tt) => gearSlots(U, t, info, tt, false) });
dcard('s013', { kicker: 'AND ONE LAST FORM', text: 'Gear 5', fs: 130, top: 180, hud: { ...H1, status: { text: 'GEAR 5 · LOCKED', on: false } }, draw: (U, t, info, tt) => { punch(U, t); gearSlots(U, t, info, tt, true); } });
dcard('s014', { kicker: 'WHEN IT ENDS', text: 'Luffy looks like an old man.', fs: 80, top: 180, hud: { ...H1, status: { text: 'COST · HIGH', on: true, color: COL.red } }, draw: (U, t, info, tt) => { const k = clamp((t - 1.2) / 1.4); U.svg('age', silhouette(760, 1000, 420, { pose: P_HIPS, face: 'smile' }) + `<path d="M 960 760 l 120 0 l -20 -20 m 20 20 l -20 20" stroke="#ffd23f" stroke-width="8" fill="none"/>` + `<g opacity="${f(0.3 + 0.7 * k)}">${person(1240, 1000, 360, { ...P_TIRED, lean: 30 }, { ...CAST.heroHoodie, face: 'worried', rim: '#9aa3ad' }).svg}${[0, 1, 2].map((i) => `<path d="M ${1205 + i * 10} ${745 + i * 12} q 18 -8 36 0" stroke="#fff" stroke-width="3" fill="none"/>`).join('')}</g>`, { z: 3 }); label(U, 'l1', 'AFTER GEAR 5 · EXHAUSTED', 1.6, t, 1120, 470, { color: COL.red, fs: 28 }); } });
const timeline60 = (U, t, info, tt, k) => { let g = `<line x1="200" y1="700" x2="1720" y2="700" stroke="#2a3460" stroke-width="10" stroke-linecap="round"/><line x1="200" y1="700" x2="${f(200 + 1520 * k)}" y2="700" stroke="${COL.yellow}" stroke-width="10" stroke-linecap="round"/>`;
  [[1, 'RUBBER'], [6, 'LIGHTNING'], [14, 'GEAR 2'], [20, 'GEAR 3'], [27, 'GEAR 4'], [40, 'GEAR 5'], [60, '?']].forEach(([d, n]) => { const x = 200 + 1520 * (d / 60), on = k >= d / 60; g += `<circle cx="${f(x)}" cy="700" r="${on ? 22 : 14}" fill="${on ? COL.yellow : '#2a3460'}"/><text x="${f(x)}" y="650" text-anchor="middle" font-family="IBM Plex Mono" font-weight="800" font-size="26" fill="${on ? '#fff' : '#5a6490'}">DAY ${d}</text><text x="${f(x)}" y="770" text-anchor="middle" font-family="IBM Plex Mono" font-weight="700" font-size="24" fill="${on ? COL.yellow : '#5a6490'}">${n}</text>`; });
  U.svg('tl', g, { z: 3 }); };
dcard('s015', { kicker: 'THE NEXT', value: '60 days', top: 200, hud: H1, draw: (U, t, info, tt) => timeline60(U, t, info, tt, clamp(t / 2) * 0.1) });
dcard('s016', { kicker: 'WHAT RUBBER CAN DO', text: '…and what it can’t.', fs: 90, top: 200, hud: H1, draw: (U, t, info, tt) => timeline60(U, t, info, tt, 0.1 + clamp(t / 3.6) * 0.6) });
dcard('s017', { kicker: 'THE STRONGEST THING YOU HAVE', text: 'also costs the most.', fs: 90, top: 200, hud: H1, draw: (U, t, info, tt) => timeline60(U, t, info, tt, 0.7 + clamp(t / 3.8) * 0.3) });

// ================================================================ helpers for the rest of the film
const hero = (U, st, at, pose = P_STAND, face = 'neutral', o = {}) => put(U, st, 'hero', at, o.h || 1.6, pose, { ...CAST.heroHoodie, ...(o.outfit || {}) }, { face, rim: o.rim || '#fff2d6', look: o.look ?? 0.4, flip: o.flip }, o.extra ? { extra: o.extra } : {});
function S3(id, set, look, cam, hudd, draw, o = {}) { sh(id, set, look, { cam, shake: o.shake, ui(U, t, info, S, st, tt) { if (o.punch) punch(U, t, o.punch === true ? '#ffffff' : o.punch); if (draw) draw(U, t, info, st, tt); chrome(U, t, info, hudd); } }); }
const lab = (U, t, items) => items.forEach(([txt, t0, x, y, c], i) => label(U, 'L' + i, txt, t0, t, x, y, c ? { color: c } : {}));

// ---------------------------------------------------------------- Day 1: the mirror (bathroom) + rubber science
const BATH = { base: 'day', fog: { color: '#e8f2f6', density: 0.02 } };
const D1 = { day: 1, time: '8:02 AM', status: ST.off };
const MIR = { pos: [0.25, 1.5, -1.25], look: [0, 1.4, 0.5], fov: 40 };
const cheek = (c, k) => { if (!c) return ''; const [hx, hy] = c.head, R = c.R, x2 = hx + R * (0.9 + 2.6 * k); return `<path d="M ${f(hx + R * 0.6)} ${f(hy - R * 0.25)} Q ${f((hx + x2) / 2)} ${f(hy - R * (0.35 + 0.2 * k))} ${f(x2)} ${f(hy + R * 0.05)} Q ${f((hx + x2) / 2)} ${f(hy + R * (0.45 + 0.2 * k))} ${f(hx + R * 0.6)} ${f(hy + R * 0.35)} Z" fill="#0b0b10"/><circle cx="${f(x2 + R * 0.1)}" cy="${f(hy + R * 0.05)}" r="${f(R * 0.22)}" fill="#0b0b10"/>`; };
S3('s018', 'bathroom', BATH, [MIR, mv(MIR, [0, 0, 0.3])], D1, (U, t, i, st, tt) => { hero(U, st, [0, 0, 0.6], P_STAND, 'neutral', { flip: true }); lab(U, t, [['TEST 1 · MIRROR', 0.3, 1240, 260]]); });
S3('s019', 'bathroom', BATH, [{ pos: [0.2, 1.55, -0.9], look: [0, 1.45, 0.6], fov: 34 }], D1, (U, t, i, st, tt) => { hero(U, st, [0, 0, 0.6], { ...P_STAND, aR: [-70, -150] }, 'worried', { flip: true, extra: (c) => cheek(c, ease.inOut(clamp((t - 0.8) / 1.2)) * 0.5) }); });
S3('s020', 'bathroom', BATH, [{ pos: [0.2, 1.55, -0.9], look: [0, 1.45, 0.6], fov: 34 }], D1, (U, t, i, st, tt) => { const k = t < 1.6 ? 0.5 + ease.out(clamp(t / 0.6)) * 0.5 : Math.max(0, 1 - (t - 1.6) / 0.15); hero(U, st, [0, 0, 0.6], { ...P_STAND, aR: [-70, -150] }, k > 0.1 ? 'worried' : 'open', { flip: true, extra: (c) => cheek(c, k) }); lab(U, t, [['CHEEK · 30 CM', 0.5, 1240, 260], ['SNAP-BACK · 0.1 S', 1.8, 1240, 350, COL.red]]); }, { shake: (t) => (t > 1.6 && t < 1.9 ? 0.03 : 0) });
const bandBar = (U, t, info) => { const k = clamp(t / 1.4); let g = `<rect x="200" y="560" width="1520" height="16" rx="8" fill="#2a3460"/>`; const x0 = 200, u = 1520 / 10; g += `<rect x="${x0}" y="520" width="${f(u * 1 * k + 4)}" height="96" rx="10" fill="#4fd06a"/>`;
  g += `<rect x="${f(x0 + u * 4)}" y="500" width="${f(u * 6)}" height="136" rx="12" fill="none" stroke="${COL.red}" stroke-width="6" stroke-dasharray="16 10" opacity="${f(clamp((t - info.w('four', 1)) / 0.3))}"/><text x="${f(x0 + u * 7)}" y="690" text-anchor="middle" font-family="IBM Plex Mono" font-weight="800" font-size="36" fill="${COL.red}" opacity="${f(clamp((t - info.w('four', 1)) / 0.3))}">BREAKS · 4× TO 10×</text>`;
  for (let i = 0; i <= 10; i++) g += `<text x="${f(x0 + u * i)}" y="480" text-anchor="middle" font-family="IBM Plex Mono" font-size="26" fill="#8a96c0">${i}×</text>`; U.svg('band', g, { z: 3 }); };
dcard('s021', { kicker: 'REAL RUBBER', text: 'Stretchy. But it has limits.', fs: 80, hud: D1, draw: bandBar });
dcard('s022', { kicker: 'NATURAL RUBBER BREAKS AT', text: 'about 4 to 10 times its length', fs: 72, hud: D1, draw: bandBar });
